/**
 * The pictures this module draws until real produce photography exists.
 *
 * All that is left of the placeholder slice. The invented week, the invented catalogue and the
 * dishes the swap sheet borrowed lines from are gone: the kept week is read from and written to
 * Convex, the draft is generated by `getDraft` and swapped through `getDraftMeal`, and the sheet
 * searches the real catalog (`useMealCatalog`). These stay because a tile and a row still
 * need a picture when a dish has none, and that fallback is not placeholder data — it is the
 * empty state's own image.
 *
 * Read across the module — never from outside `planning/`, which is what keeps it private.
 */

const EMPTY_PLATE = require("assets/placeholders/empty-plate.png");

export const EMPTY_PLATE_IMAGE = EMPTY_PLATE;

export const MEAL_IMAGE = EMPTY_PLATE;
